/** True once an archived row has outlived `retentionDays × 24h`. */
export function isExpired(
  row: SoftDeletable,
  retentionDays: number,
  now: Date = new Date(),
): boolean {
  if (row.archivedAt === null) return false;
  return (
    now.getTime() - new Date(row.archivedAt).getTime() >=
    retentionDays * 24 * 60 * 60 * 1000
  );
}
